glm::vec3 r = pj->position - pi->position;
float rLen = glm::length(r);
if (rLen > 0 && rLen < h) {
    float q = rLen / h;
    float gradSpiky = -spikyGrad * (1 / (h * h * h)) * (1 / (rLen * rLen)) * r;
    float lapSpiky = spikyLap * (1 / (h * h * h)) * (1 - q);
    glm::vec3 pressureForce = (pi->pressure + pj->pressure) / (2 * mass) * gradSpiky;
    glm::vec3 viscosityForce = viscosity * (pj->velocity - pi->velocity) / mass * lapSpiky;
    force += pressureForce + viscosityForce;
}

